});

describe('RightPanel', () => {
    const cumprimentoPreenchido = {
        forma_cumprimento: 'Memória de cálculo juntada',
        descricao_cumprimento: 'Planilha anexada após conferência do dossiê.',
    };

    const baseProps = {
        pend: buildPendencia({
            titulo: 'Pendência documental',
            categoria: 'Documentação',
            origem: 'due_ativo',
            descricao: 'Documento pendente de análise.',
            visivel_broker: true,
        }),
        ativo: null,
        expanded: false,
        currDocs: [],
        canManageDocs: false,
        isUploadingDoc: false,
        handleUploadPendenciaFiles: jest.fn(),
        handleRemovePendenciaDoc: jest.fn(),
        handleToggleExpanded: jest.fn(),
        handleClosePend: jest.fn(),
        handleShowArquivarPopup: jest.fn(),
        chatMessages: [],
        canManageChat: false,
        isLoadingChatMessages: false,
        isSendingMensagem: false,
        handleSendChatMessage: jest.fn(),
        shouldConcludePendencia: false,
    };

    it('renders the send to analysis action and calls its handler', () => {
        const handleEnviarPendenciaAnalise = jest.fn();

        render(
            <RightPanel
                {...baseProps}
                pend={buildPendencia({
                    ...baseProps.pend,
                    ...cumprimentoPreenchido,
                    visivel_broker: true,
                })}
                isEnviandoAnalise={false}
                handleEnviarPendenciaAnalise={handleEnviarPendenciaAnalise}
            />,
        );

        const sanarPendenciaActions = screen.getAllByRole('button', {
            name: /sanar pendência/i,
        });
        fireEvent.click(sanarPendenciaActions[0]);

        expect(handleEnviarPendenciaAnalise).toHaveBeenCalledTimes(1);
        expect(handleEnviarPendenciaAnalise).toHaveBeenCalledWith(cumprimentoPreenchido);
    });

    it('renders fulfillment fields below the chat', () => {
        render(
            <RightPanel
                {...baseProps}
                isEnviandoAnalise={false}
                handleEnviarPendenciaAnalise={jest.fn()}
            />,
        );

        const chatLabel = screen.getByText(/CHAT/i);
        const formaLabel = screen.getByText('FORMA DE CUMPRIMENTO');
        const descricaoField = screen.getByRole('textbox', {
            name: 'Descrição do cumprimento',
        });

        expect(chatLabel.compareDocumentPosition(formaLabel) & Node.DOCUMENT_POSITION_FOLLOWING).toBe(
            Node.DOCUMENT_POSITION_FOLLOWING,
        );
        expect(screen.getByRole('combobox', { name: 'Forma de cumprimento' })).toBeInTheDocument();
        expect(descricaoField).toBeInTheDocument();
    });

    it('disables the send action when fulfillment fields are empty', () => {
        render(
            <RightPanel
                {...baseProps}
                isEnviandoAnalise={false}
                handleEnviarPendenciaAnalise={jest.fn()}
            />,
        );

        const sanarPendenciaActions = screen.getAllByRole('button', {
            name: /sanar pendência/i,
        });

        sanarPendenciaActions.forEach((action) => {
            expect(action).toHaveProperty('disabled', true);
        });
    });

    it('enables the send action as soon as both fulfillment fields have a value', () => {
        render(
            <RightPanel
                {...baseProps}
                pend={buildPendencia({
                    ...baseProps.pend,
                    visivel_broker: true,
                    forma_cumprimento: cumprimentoPreenchido.forma_cumprimento,
                })}
                isEnviandoAnalise={false}
                handleEnviarPendenciaAnalise={jest.fn()}
            />,
        );

        const sanarPendenciaActions = screen.getAllByRole('button', {
            name: /sanar pendência/i,
        });
        sanarPendenciaActions.forEach((action) => {
            expect(action).toHaveProperty('disabled', true);
        });

        fireEvent.change(screen.getByRole('textbox', { name: 'Descrição do cumprimento' }), {
            target: { value: cumprimentoPreenchido.descricao_cumprimento },
        });

        sanarPendenciaActions.forEach((action) => {
            expect(action).toHaveProperty('disabled', false);
        });
    });

    it('sends the current textarea value on submit', () => {
        const handleEnviarPendenciaAnalise = jest.fn();

        render(
            <RightPanel
                {...baseProps}
                pend={buildPendencia({
                    ...baseProps.pend,
                    visivel_broker: true,
                    forma_cumprimento: cumprimentoPreenchido.forma_cumprimento,
                    descricao_cumprimento: 'Texto antigo ainda não consolidado.',
                })}
                isEnviandoAnalise={false}
                handleEnviarPendenciaAnalise={handleEnviarPendenciaAnalise}
            />,
        );

        fireEvent.change(screen.getByRole('textbox', { name: 'Descrição do cumprimento' }), {
            target: { value: cumprimentoPreenchido.descricao_cumprimento },
        });
        fireEvent.click(screen.getAllByRole('button', { name: /sanar pendência/i })[0]);

        expect(handleEnviarPendenciaAnalise).toHaveBeenCalledWith(cumprimentoPreenchido);
    });

    it('disables the send action while submitting', () => {
        render(
            <RightPanel
                {...baseProps}
                isEnviandoAnalise
                handleEnviarPendenciaAnalise={jest.fn()}
            />,
        );

        const sanarPendenciaActions = screen.getAllByRole('button', {
            name: /sanar pendência/i,
        });

        expect(sanarPendenciaActions).toHaveLength(2);
        sanarPendenciaActions.forEach((action) => {
            expect(action).toHaveProperty('disabled', true);
        });
    });

    it('does not render legacy vinculo sections', () => {
        render(
            <RightPanel
                {...baseProps}
                isEnviandoAnalise={false}
                handleEnviarPendenciaAnalise={jest.fn()}
            />,
        );

        expect(screen.queryByText(/PROCESSOS VINCULADOS/i)).not.toBeInTheDocument();
        expect(screen.queryByText(/CERTIDÕES VINCULADAS/i)).not.toBeInTheDocument();
        expect(screen.queryByText(/MOVIMENTAÇÕES DD VINCULADAS/i)).not.toBeInTheDocument();
    });

    it('shows conclude action when shouldConcludePendencia is true', () => {
        render(
            <RightPanel
                {...baseProps}
                pend={buildPendencia({
                    titulo: 'Pendência documental',
                    visivel_broker: true,
                })}
                shouldConcludePendencia
                isEnviandoAnalise={false}
                handleEnviarPendenciaAnalise={jest.fn()}
            />,
        );

        const concludeActions = screen.getAllByRole('button', {
            name: /concluir pendência/i,
        });

        expect(concludeActions).toHaveLength(2);
        expect(screen.queryByText('Enviar para análise')).not.toBeInTheDocument();
    });

    it('keeps analysis action when visivel_broker is false and shouldConcludePendencia is false', () => {
        render(
            <RightPanel
                {...baseProps}
                pend={buildPendencia({
                    titulo: 'Pendência documental',
                    visivel_broker: false,
                })}
                shouldConcludePendencia={false}
                isEnviandoAnalise={false}
                handleEnviarPendenciaAnalise={jest.fn()}
            />,
        );

        expect(screen.getAllByRole('button', { name: /sanar pendência/i })).toHaveLength(2);
        expect(screen.queryByRole('button', { name: /concluir pendência/i })).not.toBeInTheDocument();
    });

    it('keeps conclude action enabled when pendencia is already in analysis', () => {
        render(
            <RightPanel
                {...baseProps}
                pend={buildPendencia({
                    titulo: 'Pendência documental',
                    visivel_broker: true,
                    status: PENDENCIA_STATUS.EM_ANALISE,
                    ...cumprimentoPreenchido,
                })}
                shouldConcludePendencia
                isEnviandoAnalise={false}
                handleEnviarPendenciaAnalise={jest.fn()}
            />,
        );

        const concludeActions = screen.getAllByRole('button', {
            name: /concluir pendência/i,
        });

        concludeActions.forEach((action) => {
            expect(action).toHaveProperty('disabled', false);
        });
    });
});

