'use client';

import { COLORS, withAlpha } from '@/app/crm/gerencial-broker/_constants/colors';
import { Button } from '@/components/ui/button';
import { Archive, ArrowLeft, ArrowRight } from 'lucide-react';
import type { TArquivamentosScreenVM } from '../../ViewModels/useViewModelArquivamentosScreen';
import { DueCard } from '../DueCards/DueCard';
import { DueCardsGridSkeleton } from '../DueCards/DueCardSkeleton';
import {
    DUE_CARDS_GRID_CONTAINER_CLASS,
    getDueCardsGridClassName,
} from '../DueCards/dueCardsGridClassName';

export function ArquivamentosScreenView({
    isLoading,
    isFetching,
    filteredItems,
    totalItems,
    getPendenciasData,
    getObsCount,
    getCessionariosLista,
    getTotalPctCessao,
    getIdwallStatus,
    getEscrituraStatus,
    handlers,
    page,
    totalPages,
    hasNextPage,
    hasPreviousPage,
    goToNextPage,
    goToPreviousPage,
    rootRef,
}: TArquivamentosScreenVM) {
    if (isLoading) {
        return <DueCardsGridSkeleton variant="arquivado" />;
    }

    if (filteredItems.length === 0 && totalItems === 0) {
        return (
            <div
                className="flex flex-col items-center justify-center rounded-2xl py-16"
                style={{
                    border: `2px dashed ${withAlpha(COLORS.border, 0.5)}`,
                    background: withAlpha(COLORS.border, 0.04),
                }}
            >
                <Archive
                    className="mb-3 size-12 stroke-[1.5] text-muted-foreground"
                    strokeWidth={1.5}
                    aria-hidden
                />
                <div className="text-sm font-semibold" style={{ color: COLORS.textDim }}>
                    Nenhum ativo arquivado para o filtro atual
                </div>
                <div className="mt-1 text-xs" style={{ color: withAlpha(COLORS.textDim, 0.6) }}>
                    Tente alterar os filtros ou realizar uma nova busca
                </div>
            </div>
        );
    }

    return (
        <div ref={rootRef} className="flex flex-col gap-4">
            {filteredItems.length > 0 ? (
                <div className={DUE_CARDS_GRID_CONTAINER_CLASS}>
                    <div className={getDueCardsGridClassName()}>
                        {filteredItems.map((item) => (
                            <DueCard
                                key={item.id}
                                item={item}
                                pendenciasData={getPendenciasData(item)}
                                obsCount={getObsCount(item)}
                                cessionariosLista={getCessionariosLista(item)}
                                totalPctCessao={getTotalPctCessao(item)}
                                idWallStatus={getIdwallStatus(item)}
                                escrituraStatusResolved={getEscrituraStatus(item)}
                                handlers={handlers}
                            />
                        ))}
                    </div>
                </div>
            ) : (
                <div className="py-10 text-center text-sm text-muted-foreground">
                    Nenhum resultado para o filtro selecionado
                </div>
            )}

            {totalItems > 0 && (
                <div
                    className="flex flex-col gap-3 rounded-xl border px-4 py-3 md:flex-row md:items-center md:justify-between"
                    style={{
                        borderColor: withAlpha(COLORS.border, 0.45),
                        background: withAlpha(COLORS.card, 0.65),
                    }}
                >
                    <div className="text-sm" style={{ color: COLORS.textDim }}>
                        {`Pagina ${page} de ${totalPages}`}
                        {isFetching ? ' • Carregando...' : ''}
                    </div>

                    <div className="flex items-center gap-2">
                        <Button
                            onClick={goToPreviousPage}
                            disabled={!hasPreviousPage || isFetching}
                            variant="outline"
                            className="group rounded-lg px-3 py-2 text-sm font-semibold transition disabled:cursor-not-allowed disabled:opacity-50"
                            style={{
                                border: `1px solid ${withAlpha(COLORS.border, 0.5)}`,
                                color: COLORS.text,
                                background: withAlpha(COLORS.card, 0.65),
                            }}
                        >
                            <ArrowLeft className="size-4 transition-transform duration-200 group-hover:-translate-x-1" />
                            Anterior
                        </Button>
                        <Button
                            onClick={goToNextPage}
                            disabled={!hasNextPage || isFetching}
                            variant="outline"
                            className="group rounded-lg px-3 py-2 text-sm font-semibold transition disabled:cursor-not-allowed disabled:opacity-50"
                            style={{
                                border: `1px solid ${withAlpha(COLORS.border, 0.5)}`,
                                color: COLORS.text,
                                background: withAlpha(COLORS.card, 0.65),
                            }}
                        >
                            Proxima
                            <ArrowRight className="size-4 transition-transform duration-200 group-hover:translate-x-1" />
                        </Button>
                    </div>
                </div>
            )}
        </div>
    );
}

