'use client';

import { COLORS, withAlpha } from '@/app/crm/gerencial-broker/_constants/colors';
import {
    Carousel,
    type CarouselApi,
    CarouselContent,
    CarouselItem,
} from '@/components/ui/carousel';
import { useIsBelowSm } from '@/hooks/use-is-below-sm';
import { useCallback, useEffect, useState } from 'react';
import type { IDueCardProps } from '../../interfaces/dueCard';
import type { TDueDiligenceDetailedCardItem } from '../../types/dueItem';
import { DueCard } from './DueCard';
import {
    DUE_CARDS_GRID_CONTAINER_CLASS,
    getDueCardsGridClassName,
} from './dueCardsGridClassName';

interface IDueCardsListLayoutProps {
    items: TDueDiligenceDetailedCardItem[];
    handlers: IDueCardProps['handlers'];
    getPendenciasData: (item: TDueDiligenceDetailedCardItem) => IDueCardProps['pendenciasData'];
    getObsCount: (item: TDueDiligenceDetailedCardItem) => number;
    getCessionariosLista: (item: TDueDiligenceDetailedCardItem) => IDueCardProps['cessionariosLista'];
    getTotalPctCessao: (item: TDueDiligenceDetailedCardItem) => number;
    getIdwallStatus: (item: TDueDiligenceDetailedCardItem) => string;
    getEscrituraStatus: (item: TDueDiligenceDetailedCardItem) => string | null | undefined;
    avancarCessaoItemId: string | null;
    isAvancarEmLiquidacaoLoadingForDueId: (dueId: string | number) => boolean;
    isEnviarPosAquisicaoLoadingForDueId: (dueId: string | number) => boolean;
}

function DueCardListItem({
    item,
    pendenciasData,
    obsCount,
    cessionariosLista,
    totalPctCessao,
    idWallStatus,
    escrituraStatusResolved,
    handlers,
    isAvancarCessaoLoading,
    isAvancarEmLiquidacaoLoading,
    isEnviarPosAquisicaoLoading,
}: Pick<
    IDueCardProps,
    | 'item'
    | 'pendenciasData'
    | 'obsCount'
    | 'cessionariosLista'
    | 'totalPctCessao'
    | 'idWallStatus'
    | 'escrituraStatusResolved'
    | 'handlers'
    | 'isAvancarCessaoLoading'
    | 'isAvancarEmLiquidacaoLoading'
    | 'isEnviarPosAquisicaoLoading'
>) {
    return (
        <DueCard
            item={item}
            pendenciasData={pendenciasData}
            obsCount={obsCount}
            cessionariosLista={cessionariosLista}
            totalPctCessao={totalPctCessao}
            idWallStatus={idWallStatus}
            escrituraStatusResolved={escrituraStatusResolved}
            handlers={handlers}
            isAvancarCessaoLoading={isAvancarCessaoLoading}
            isAvancarEmLiquidacaoLoading={isAvancarEmLiquidacaoLoading}
            isEnviarPosAquisicaoLoading={isEnviarPosAquisicaoLoading}
        />
    );
}

function DueCardsGrid({
    items,
    handlers,
    getPendenciasData,
    getObsCount,
    getCessionariosLista,
    getTotalPctCessao,
    getIdwallStatus,
    getEscrituraStatus,
    avancarCessaoItemId,
    isAvancarEmLiquidacaoLoadingForDueId,
    isEnviarPosAquisicaoLoadingForDueId,
}: IDueCardsListLayoutProps) {
    return (
        <div className={DUE_CARDS_GRID_CONTAINER_CLASS}>
            <div className={getDueCardsGridClassName()} data-testid="due-cards-desktop-grid">
                {items.map((item) => (
                    <DueCardListItem
                        key={item.id}
                        item={item}
                        pendenciasData={getPendenciasData(item)}
                        obsCount={getObsCount(item)}
                        cessionariosLista={getCessionariosLista(item)}
                        totalPctCessao={getTotalPctCessao(item)}
                        idWallStatus={getIdwallStatus(item)}
                        escrituraStatusResolved={getEscrituraStatus(item)}
                        handlers={handlers}
                        isAvancarCessaoLoading={avancarCessaoItemId === item.id}
                        isAvancarEmLiquidacaoLoading={isAvancarEmLiquidacaoLoadingForDueId(item.id)}
                        isEnviarPosAquisicaoLoading={isEnviarPosAquisicaoLoadingForDueId(item.id)}
                    />
                ))}
            </div>
        </div>
    );
}

function DueCardsCarousel({
    items,
    handlers,
    getPendenciasData,
    getObsCount,
    getCessionariosLista,
    getTotalPctCessao,
    getIdwallStatus,
    getEscrituraStatus,
    avancarCessaoItemId,
    isAvancarEmLiquidacaoLoadingForDueId,
    isEnviarPosAquisicaoLoadingForDueId,
}: IDueCardsListLayoutProps) {
    const [carouselApi, setCarouselApi] = useState<CarouselApi>();
    const [selectedIndex, setSelectedIndex] = useState(0);
    const [snapCount, setSnapCount] = useState(items.length);

    const syncCarouselIndicators = useCallback(
        (api: CarouselApi) => {
            if (!api) return;

            const nextSelectedIndex = api.selectedScrollSnap();

            setSelectedIndex(Number.isFinite(nextSelectedIndex) ? nextSelectedIndex : 0);
            setSnapCount(Math.max(api.scrollSnapList().length, items.length));
        },
        [items.length],
    );

    useEffect(() => {
        if (!carouselApi) return;

        syncCarouselIndicators(carouselApi);
        carouselApi.on('select', syncCarouselIndicators);
        carouselApi.on('reInit', syncCarouselIndicators);

        return () => {
            carouselApi.off('select', syncCarouselIndicators);
            carouselApi.off('reInit', syncCarouselIndicators);
        };
    }, [carouselApi, syncCarouselIndicators]);

    return (
        <Carousel
            setApi={setCarouselApi}
            opts={{
                align: 'start',
            }}
            className="w-full"
            data-testid="due-cards-mobile-carousel"
        >
            <CarouselContent className="-ml-4">
                {items.map((item) => (
                    <CarouselItem key={item.id} className="basis-full pl-4">
                        <DueCardListItem
                            item={item}
                            pendenciasData={getPendenciasData(item)}
                            obsCount={getObsCount(item)}
                            cessionariosLista={getCessionariosLista(item)}
                            totalPctCessao={getTotalPctCessao(item)}
                            idWallStatus={getIdwallStatus(item)}
                            escrituraStatusResolved={getEscrituraStatus(item)}
                            handlers={handlers}
                            isAvancarCessaoLoading={avancarCessaoItemId === item.id}
                            isAvancarEmLiquidacaoLoading={isAvancarEmLiquidacaoLoadingForDueId(
                                item.id,
                            )}
                            isEnviarPosAquisicaoLoading={isEnviarPosAquisicaoLoadingForDueId(
                                item.id,
                            )}
                        />
                    </CarouselItem>
                ))}
            </CarouselContent>

            <div
                className="mt-3 flex items-center justify-center gap-2"
                aria-label="Navegação dos cards"
            >
                {Array.from({ length: snapCount }).map((_, index) => {
                    const isSelected = selectedIndex === index;

                    return (
                        <button
                            key={index}
                            type="button"
                            aria-label={`Ir para o card ${index + 1}`}

