34	export function navigateToDueDiligenceMain(router: AppRouterInstance): void {
35	    const urlParams = new URLSearchParams(window.location.search);
36	    const prevPageParams = urlParams.get('prevPageParams');
37	
38	    if (prevPageParams) {
39	        void router.push(`${APP_ROUTES.private.dueDiligence2.name}${prevPageParams}`);
40	        return;
41	    }
42	
43	    void router.push(APP_ROUTES.private.dueDiligence2.name);
44	}
45	
46	export function getPhaseFromUrl(): ActiveViewType | null {
47	    const urlParams = new URLSearchParams(window.location.search);
48	    const encodedParams = urlParams.get('prevPageParams');
49	
50	    if (!encodedParams) return null;
51	
52	    try {
53	        const decodedString = decodeURIComponent(encodedParams).replace(/^\?/, '');
54	        const innerParams = new URLSearchParams(decodedString);
55	
56	        return (innerParams.get('activeView') as ActiveViewType) || ActiveViewType.DUE_DILIGENCE;
57	    } catch (e) {
58	        console.error('Erro ao decodificar parâmetros:', e);
59	        return null;
60	    }
61	}
62	
63	export function getObsCount(item: DueObsCessaoIdwallFields): number {
64	    return item.observacoes_count ?? 0;
65	}
66	
67	export function buildPathWithPrevParams(basePath: string): string {
68	    if (typeof window === 'undefined') return basePath;
69	
70	    const urlParams = new URLSearchParams(window.location.search);
71	
72	    const prevValue = urlParams.get('prevPageParams') ?? window.location.search;
73	    if (!prevValue) return basePath;
74	
75	    const queryIndex = basePath.indexOf('?');
76	    const pathname = queryIndex === -1 ? basePath : basePath.slice(0, queryIndex);
77	    const nextParams = new URLSearchParams(queryIndex === -1 ? '' : basePath.slice(queryIndex + 1));
78	    nextParams.set('prevPageParams', prevValue);
79	    const qs = nextParams.toString();
80	    return qs ? `${pathname}?${qs}` : pathname;
81	}
82	
83	/** Remove lixo de query embutido no filtro (ex.: credor com `?prevPageParams=` por URL malformada). */
84	export function sanitizePendenciasCredorFilter(raw: string): string {
85	    const trimmed = raw.trim();
86	    const cut = trimmed.search(/[?&]/);
87	    return cut === -1 ? trimmed : trimmed.slice(0, cut).trim();
88	}
