import type { TPendencia, TPendenciaListagem } from '../types/pendencia';
import { countOpenPendencias } from '../utils/getPendenciasData';
import { getPendenciasFromListagem } from '../utils/pendenciaHelpers';
import { PENDENCIA_STATUS } from '../utils/pendenciaStatus';
import { computePendenciaMap } from '../utils/situacaoJuridica';

function buildPendencia(overrides: Partial<TPendencia> & { id: number }): TPendencia {
    return {
        titulo: 'Ressalva',
        categoria: 'documental',
        descricao: 'Descrição',
        especie: 'ativo',
        natureza: 'operacional',
        vinculo: null,
        severidade: 'media',
        impedimento: false,
        status: PENDENCIA_STATUS.NAO_RESOLVIDA,
        registrado_por: 'analista@celer.com',
        data_registro: '2026-08-16',
        documentos: [],
        esclarecimento: null,
        tentativas_anteriores: [],
        ...overrides,
    };
}

function buildGrupoCertidao() {
    return {
        titular: { tipo: 'cedente' as const, id: 'cedente-1', nome: 'Fulano', papel: 'Titular', natureza: 'PF' as const },
        resumo: { abertas: 1, total_pendencias: 1, divida_total: 0 },
        itens: [
            buildPendencia({
                id: 2,
                especie: 'certidao',
                origem: 'certidoes',
                vinculo: { kind: 'certidao', id: 'certidao-1' },
            }),
        ],
    };
}

function buildGrupoProcesso() {
    return {
        titular: { tipo: 'cedente' as const, id: 'cedente-1', nome: 'Fulano', papel: 'Titular', natureza: 'PF' as const },
        resumo: { abertas: 1, total_pendencias: 1, divida_total: 0 },
        itens: [
            buildPendencia({
                id: 3,
                especie: 'processo',
                origem: 'situacao_processual',
                vinculo: { kind: 'processo', id: 'processo-1' },
            }),
        ],
    };
}

/** Formato canônico V2: `certidoes`/`processos` como array de grupos. */
function buildListagemCanonina(): TPendenciaListagem {
    return {
        ativo: [buildPendencia({ id: 1, origem: 'checklist' })],
        certidoes: [buildGrupoCertidao()],
        processos: [buildGrupoProcesso()],
    };
}

describe('getPendenciasFromListagem', () => {
    it('achata a listagem canônica preservando ativo, certidões e processos', () => {
        const pendencias = getPendenciasFromListagem(buildListagemCanonina());

        expect(pendencias.map((pendencia) => pendencia.id)).toEqual([1, 2, 3]);
    });
});

describe('computePendenciaMap com listagem agrupada', () => {
    it('marca processos e certidões vinculados sem quebrar', () => {
        const item = { id: 'due-1', nome_credor: 'Fulano' };

        const { processosEmPendencia, certidoesEmPendencia, pessoaPendMap } = computePendenciaMap(
            item,
            [{ ...item, pendencias: buildListagemCanonina() }],
        );

        expect([...processosEmPendencia]).toEqual(['processo-1']);
        expect([...certidoesEmPendencia]).toEqual(['certidao-1']);
        expect(pessoaPendMap['analista@celer.com']).toMatchObject({
            total: 3,
            processos: 1,
            certidoes: 1,
        });
    });
});

describe('countOpenPendencias com listagem agrupada', () => {
    it('conta pendências abertas das três espécies', () => {
        expect(countOpenPendencias({ pendencias: buildListagemCanonina() })).toBe(3);
    });
});

